using System.Text; using SqlSchemaCompare.Core.Interfaces; using SqlSchemaCompare.Core.Models;
namespace SqlSchemaCompare.Core.ScriptGeneration;
public sealed class SqlScriptGenerator : IScriptGenerator
{ public string Generate(IEnumerable<SchemaDifference> differences,string sourceDatabase,string targetDatabase,bool allowDestructiveChanges=false){var sb=new StringBuilder();sb.AppendLine($"/*\nDATABASE SCHEMA SYNC SCRIPT\nSource Database : {sourceDatabase}\nTarget Database : {targetDatabase}\nGenerated At    : {DateTime.Now:yyyy-MM-dd HH:mm:ss}\n\nReview the script before executing it in production.\n*/\n");foreach(var d in differences.Where(x=>x.IsSelected).OrderBy(x=>Order(x.ObjectType))){var sql=Build(d,allowDestructiveChanges);if(!string.IsNullOrWhiteSpace(sql))sb.AppendLine(sql+"\nGO\n");}return sb.ToString();}
 static int Order(SchemaObjectType x)=>x switch{SchemaObjectType.Table=>1,SchemaObjectType.Column=>2,SchemaObjectType.PrimaryKey=>3,SchemaObjectType.UniqueConstraint=>4,SchemaObjectType.DefaultConstraint=>5,SchemaObjectType.Index=>6,SchemaObjectType.ForeignKey=>7,SchemaObjectType.View=>8,SchemaObjectType.Function=>9,SchemaObjectType.StoredProcedure=>10,SchemaObjectType.Trigger=>11,_=>99};
 static string Build(SchemaDifference d,bool allow){var q=$"[{d.SchemaName}].[{d.ObjectName}]";if(d.DifferenceType==DifferenceType.Removed)return allow?d.ObjectType switch{SchemaObjectType.Table=>$"IF OBJECT_ID(N'{d.SchemaName}.{d.ObjectName}', N'U') IS NOT NULL DROP TABLE {q};",_=>"-- Destructive removal requires explicit review: "+d.Description}:"-- "+d.Description; if(d.ObjectType==SchemaObjectType.Column&&d.DifferenceType==DifferenceType.Added){var parts=(d.SourceDefinition??"NVARCHAR(255) NULL").Split(' ',2);var typ=parts[0];var nullability=parts.Length>1?parts[1]:"NULL";var def= nullability.Contains("NOT NULL",StringComparison.OrdinalIgnoreCase)?" CONSTRAINT [DF_"+d.ObjectName.Replace('.','_')+"] DEFAULT (0) WITH VALUES":"";var table=d.ObjectName[..d.ObjectName.LastIndexOf('.')];var col=d.ObjectName[(d.ObjectName.LastIndexOf('.')+1)..];return $"IF COL_LENGTH(N'{d.SchemaName}.{table}', N'{col}') IS NULL\nBEGIN\n    ALTER TABLE [{d.SchemaName}].[{table}] ADD [{col}] {typ} {nullability}{def};\nEND";} if(d.ObjectType==SchemaObjectType.Index&&d.DifferenceType==DifferenceType.Added){var line=d.SourceDefinition??"";var on=line.IndexOf(" ON ",StringComparison.OrdinalIgnoreCase);var name=d.ObjectName;var rest=on>=0?line[(on+4)..]:$"[{d.SchemaName}].[{d.ObjectName}]";return $"IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'{name}' AND object_id = OBJECT_ID(N'{d.SchemaName}.{d.ObjectName}'))\nBEGIN\n    CREATE NONCLUSTERED INDEX [{name}] ON {rest};\nEND";}if(d.ObjectType is SchemaObjectType.View or SchemaObjectType.Function or SchemaObjectType.StoredProcedure)return d.SourceDefinition??$"-- Review definition for {q}";return "-- Review: "+d.Description;}
}
